// PATCH /api/records/:id  — editors may update records
app.patch('/api/records/:id', async (req, res) => {
  // role comes straight from the JWT the client sent
  const roles = req.jwt.roles;            // e.g. ['editor']
  if (!roles.includes('editor')) {
    return res.status(403).send('forbidden');
  }
  // any editor may patch ANY record id
  const record = await db.records.findById(req.params.id);
  Object.assign(record, req.body);
  await db.records.save(record);
  res.json(record);
});
